import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2 } from 'react-icons/fi';
import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminServices = () => {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    icon: '',
    image: '',
    is_active: true,
    order: 0,
  });

  useEffect(() => {
    fetchServices();
  }, []);

  const fetchServices = async () => {
    try {
      const response = await api.get('/api/services/all');
      setServices(response.data);
    } catch (error) {
      toast.error('Failed to load services');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingService) {
        await api.put(`/api/services/${editingService.id}`, formData);
        toast.success('Service updated successfully');
      } else {
        await api.post('/api/services/', formData);
        toast.success('Service created successfully');
      }
      setModalOpen(false);
      setEditingService(null);
      setFormData({
        title: '',
        description: '',
        icon: '',
        image: '',
        is_active: true,
        order: 0,
      });
      fetchServices();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this service?')) {
      try {
        await api.delete(`/api/services/${id}`);
        toast.success('Service deleted successfully');
        fetchServices();
      } catch (error) {
        toast.error('Failed to delete service');
      }
    }
  };

  const handleEdit = (service) => {
    setEditingService(service);
    setFormData({
      title: service.title,
      description: service.description || '',
      icon: service.icon || '',
      image: service.image || '',
      is_active: service.is_active,
      order: service.order || 0,
    });
    setModalOpen(true);
  };

  const columns = [
    { key: 'icon', label: 'Icon', render: (val) => <span className="text-2xl">{val || '📌'}</span> },
    { key: 'title', label: 'Title' },
    { key: 'description', label: 'Description', render: (val) => val?.slice(0, 50) + '...' },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${
          val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
        }`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleEdit(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEdit2 />
          </button>
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Services Management</h1>
        <button
          onClick={() => {
            setEditingService(null);
            setFormData({
              title: '',
              description: '',
              icon: '',
              image: '',
              is_active: true,
              order: 0,
            });
            setModalOpen(true);
          }}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Service</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={services}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setEditingService(null);
        }}
        title={editingService ? 'Edit Service' : 'Create Service'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Title *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="admin-input"
                rows="3"
              />
            </div>
            <div>
              <label className="admin-label">Icon (Emoji or HTML)</label>
              <input
                type="text"
                value={formData.icon}
                onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                className="admin-input"
                placeholder="📚"
              />
            </div>
            <div>
              <label className="admin-label">Image URL</label>
              <input
                type="text"
                value={formData.image}
                onChange={(e) => setFormData({ ...formData, image: e.target.value })}
                className="admin-input"
                placeholder="https://example.com/image.jpg"
              />
            </div>
            <div>
              <label className="admin-label">Order</label>
              <input
                type="number"
                value={formData.order}
                onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 0 })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_active}
                  onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                />
                <span>Active</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                setEditingService(null);
              }}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingService ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminServices;
